import random
class RandomizedSet:
    def __init__(self):
        self.values = []
        self.index_by_val = {}
    def insert(self, val: int) -> bool:
        if val in self.index_by_val:
            return False
        self.index_by_val[val] = len(self.values)
        self.values.append(val)
        return True
    def remove(self, val: int) -> bool:
        if val not in self.index_by_val:
            return False
        remove_idx = self.index_by_val[val]
        last_val = self.values[-1]
        self.values[remove_idx] = last_val
        self.index_by_val[last_val] = remove_idx
        self.values.pop()
        del self.index_by_val[val]
        return True
    def getRandom(self) -> int:
        return random.choice(self.values)
